std::string json_escape(const std::string& value) {
    std::ostringstream stream;
    for (unsigned char ch : value) {
        switch (ch) {
            case '\"':
                stream << "\\\"";
                break;
            case '\\':
                stream << "\\\\";
                break;
            case '\b':
                stream << "\\b";
                break;
            case '\f':
                stream << "\\f";
                break;
            case '\n':
                stream << "\\n";
                break;
            case '\r':
                stream << "\\r";
                break;
            case '\t':
                stream << "\\t";
                break;
            default:
                if (ch < 0x20U) {
                    stream << "\\u"
                           << std::hex
                           << std::setw(4)
                           << std::setfill('0')
                           << static_cast<unsigned int>(ch)
                           << std::dec
                           << std::setfill(' ');
                } else {
                    stream << static_cast<char>(ch);
                }
                break;
        }
    }
    return stream.str();
}

void print_json_string(const std::string& value) {
    std::cout << "\"" << json_escape(value) << "\"";
}

void print_json_string_view(std::string_view value) {
    print_json_string(std::string(value));
}

void print_json_string_array(const std::vector<std::string>& values) {
    std::cout << "[";
    for (std::size_t index = 0U; index < values.size(); ++index) {
        if (index != 0U) {
            std::cout << ", ";
        }
        print_json_string(values[index]);
    }
    std::cout << "]";
}

void print_json_int_array(const std::vector<int>& values) {
    std::cout << "[";
    for (std::size_t index = 0U; index < values.size(); ++index) {
        if (index != 0U) {
            std::cout << ", ";
        }
        std::cout << values[index];
    }
    std::cout << "]";
}

std::string shell_quote(const std::string& value) {
    if (value.empty()) {
        return "''";
    }
    std::string quoted = "'";
    for (const char ch : value) {
        if (ch == '\'') {
            quoted += "'\\''";
        } else {
            quoted += ch;
        }
    }
    quoted += "'";
    return quoted;
}

std::string build_shell_command(const std::string& launch_command, const std::vector<std::string>& arguments) {
    std::string command = shell_quote(launch_command);
    for (const auto& argument : arguments) {
        command += " ";
        command += shell_quote(argument);
    }
    return command;
}

int normalize_system_exit_code(int system_status) {
    if (system_status == -1) {
        return -1;
    }
#if defined(_WIN32)
    return system_status;
#else
    if (WIFEXITED(system_status)) {
        return WEXITSTATUS(system_status);
    }
    if (WIFSIGNALED(system_status)) {
        return 128 + WTERMSIG(system_status);
    }
    return system_status;
#endif
}

