    std::cout << "    \"rootObjectCount\": " << root_object_count << ",\n";
    std::cout << "    \"rootRecordIndexes\": ";
    print_json_record_index_array(root_record_indexes);
    std::cout << ",\n";
    std::cout << "    \"leafObjectCount\": " << leaf_record_indexes.size() << ",\n";
